def deplacer_vers_prive(apps, schema_editor):
    """Déplace les documents déjà envoyés du dossier media public vers le
    dossier privé (même chemin relatif : rien à changer en base)."""
    User = apps.get_model('marketplace', 'User')
    for user in User.objects.exclude(piece_identite='', permis_conduire='').iterator():
        for champ in ('piece_identite', 'permis_conduire'):
            nom = getattr(user, champ).name
            if not nom:
                continue
            source = os.path.join(settings.MEDIA_ROOT, nom)
            cible = os.path.join(settings.PRIVATE_MEDIA_ROOT, nom)
            if os.path.exists(source) and not os.path.exists(cible):
                os.makedirs(os.path.dirname(cible), exist_ok=True)
                shutil.move(source, cible)


